export function glowSprite(hex, scale = 2, opacity = 0.75) {
  const mat = new THREE.SpriteMaterial({
    map: glowTexture(), color: hex, transparent: true, opacity,
    blending: THREE.AdditiveBlending, depthWrite: false, fog: true,
