sun.shadow.camera.top = QUALITY.shadowRadius;
sun.shadow.camera.bottom = -QUALITY.shadowRadius;
sun.shadow.bias = -0.0008;
sun.shadow.normalBias = 0.035;
scene.add(sun);
scene.add(sun.target);
