function ridgeGeometry(radius, heightMin, heightMax, seed, baseY = -5) {
  const segments = 84;
  const rng = seeded(seed);
  const positions = [], colors = [];
  const cA = new THREE.Color(0x243b3c), cB = new THREE.Color(0x395451);
  let prevH = heightMin + rng() * (heightMax - heightMin);
  for (let i = 0; i < segments; i++) {
    const a0 = (i / segments) * TAU, a1 = ((i + 1) / segments) * TAU;
    const h = heightMin + rng() * (heightMax - heightMin);
    const h2 = (h + prevH) * 0.5 + rng() * 4;
    const x0 = Math.cos(a0) * radius, z0 = Math.sin(a0) * radius;
    const x1 = Math.cos(a1) * radius, z1 = Math.sin(a1) * radius;
    const am = (a0 + a1) / 2;
    const px = Math.cos(am) * (radius - 9), pz = Math.sin(am) * (radius - 9);
    // two triangles per segment, peak shared
    positions.push(x0, baseY, z0, x1, baseY, z1, px, Math.max(h, h2), pz);
    const tint = 0.7 + rng() * 0.4;
    const c = cA.clone().lerp(cB, rng() * 0.85).multiplyScalar(tint);
    for (let k = 0; k < 3; k++) colors.push(c.r, c.g, c.b);
    prevH = h2;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geo.computeVertexNormals();
  return geo;
}

