export function terrainHeight(x, z) {
  let h = baseHeight(x, z);
  const d = streamDist(x, z);
  if (d < 10) h = lerp(-1.5, h, smoothstep(3.0, 10.0, d));
  const r = Math.hypot(x, z);
  if (r > 92) h -= (r - 92) * 0.55;
  return h;
}

