579: function updatePlayer(dt) {
580:   if (!game.started || game.ended) {
581:     player.vx = damp(player.vx, 0, 8, dt);
582:     player.vz = damp(player.vz, 0, 8, dt);
583:   } else if (game.rollT > 0) {
584:     // rolling: velocity handled by roll impulse
585:   } else if (game.mode === 'explore' || game.mode === 'hunt') {
586:     const { ix, fwd } = moveInput();
587:     const c = cameraBasis();
588:     const dx = c.rx * ix + c.fx * fwd;
589:     const dz = c.rz * ix + c.fz * fwd;
590:     let speed = 4.6;
591:     if (player.wading) speed *= 0.55;
592:     const targetVx = dx * speed, targetVz = dz * speed;
593:     const accel = 14;
594:     player.vx = damp(player.vx, targetVx, accel, dt);
595:     player.vz = damp(player.vz, targetVz, accel, dt);
596:     if (dx || dz) {
597:       const target = Math.atan2(dx, dz);
598:       let diff = ((target - player.face + Math.PI * 3) % TAU) - Math.PI;
599:       player.face += diff * Math.min(1, dt * 14);
600:     }
601:   } else {
602:     player.vx = damp(player.vx, 0, 12, dt);
603:     player.vz = damp(player.vz, 0, 12, dt);
604:   }
605: 
606:   player.x += player.vx * dt;
607:   player.z += player.vz * dt;
608:   const r = Math.hypot(player.x, player.z);
609:   if (r > 88) { player.x = player.x / r * 88; player.z = player.z / r * 88; }
610: 
611:   // Trees & landmarks
612:   for (const t of world.treeColliders) {
613:     const dx = player.x - t.x, dz = player.z - t.z;
614:     const d = Math.hypot(dx, dz);
615:     const min = t.r + 0.45;
616:     if (d < min && d > 0.001) {
617:       player.x = t.x + dx / d * min;
618:       player.z = t.z + dz / d * min;
619:     }
620:   }
621:   const ds = Math.hypot(player.x - SHRINE_POS.x, player.z - SHRINE_POS.z);
622:   if (ds < 3.9 && ds > 0.01) {
623:     const k = 3.9 / ds;
624:     player.x = SHRINE_POS.x + (player.x - SHRINE_POS.x) * k;
625:     player.z = SHRINE_POS.z + (player.z - SHRINE_POS.z) * k;
626:   }
627: 
628:   player.y = groundHeight(player.x, player.z);
629:   const rawGround = player.y;
630:   if (rawGround < WATER_Y - 0.26) player.y = WATER_Y - 0.26;
631:   player.wading = rawGround < WATER_Y + 0.02;
632:   player.speed = Math.hypot(player.vx, player.vz);
633: 
634:   if (player.wading && player.speed > 1 && Math.random() < dt * 16) {
635:     particles.emit(player.x, WATER_Y + 0.05, player.z, 0x9fd8cf,
636:       { count: 2, speed: 1.1, spread: 0.7, up: 1.2, life: 0.5, gravity: -5, drag: 1 });
637:   } else if (player.speed > 2 && Math.random() < dt * 5) {
638:     particles.emit(player.x - Math.sin(player.face) * 0.2, player.y + 0.06, player.z - Math.cos(player.face) * 0.2, 0x9d9a7e,
639:       { count: 1, speed: 0.5, spread: 0.3, up: 0.35, life: 0.5, gravity: 0.2, drag: 3 });
640:   }
641: 
642:   playerRig.root.position.set(player.x, player.y, player.z);
643:   playerRig.root.rotation.y = player.face;
644:   animatePlayer(playerRig, dt, game.time, {
645:     speed: player.speed,
646:     attack: game.attackT,
647:     spell: game.spellT,
648:     roll: game.rollT,
649:     hurt: game.hurt,
650:   });
651:   game.attackT = Math.max(0, game.attackT - dt);
652:   game.spellT = Math.max(0, game.spellT - dt);
653:   game.rollT = Math.max(0, game.rollT - dt);
654:   game.attackCd = Math.max(0, game.attackCd - dt);
655:   game.spellCd = Math.max(0, game.spellCd - dt);
656:   game.rollCd = Math.max(0, game.rollCd - dt);
657:   game.invuln = Math.max(0, game.invuln - dt);
658:   game.hurt = Math.max(0, game.hurt - dt);
659:   game.shake = Math.max(0, game.shake - dt);
660:   game.attackFlash = Math.max(0, game.attackFlash - dt);
661: 
662:   if (game.hurtFlash > 0) {
663:     game.hurtFlash -= dt;
664:     if (game.hurtFlash <= 0) setVignette('');
665:   }
666: 
667:   // slow out-of-combat recovery
668:   game.regenDelay = Math.max(0, game.regenDelay - dt);
669:   if (game.regenDelay <= 0 && game.hp < 100 && !game.ended) {
670:     game.hp = Math.min(100, game.hp + dt * 3.2);
671:   }
672:   game.will = Math.min(100, game.will + dt * 6.5);
673: }
