675: function updateDog(dt) {
676:   const back = -Math.sin(player.face), backz = -Math.cos(player.face);
677:   const side = Math.cos(player.face), sidez = -Math.sin(player.face);
678:   const tx = player.x + back * 1.6 + side * 1.1;
679:   const tz = player.z + backz * 1.6 + sidez * 1.1;
680:   const dx = tx - dog.root.position.x, dz = tz - dog.root.position.z;
681:   const d = Math.hypot(dx, dz);
682:   let moving = 0;
683:   if (d > 0.5) {
684:     const speed = d > 6 ? 6.2 : 3.4;
685:     dog.root.position.x += dx / d * Math.min(d, speed * dt);
686:     dog.root.position.z += dz / d * Math.min(d, speed * dt);
687:     moving = 1;
688:     const ang = Math.atan2(dx, dz);
689:     let diff = ((ang - dog.root.rotation.y + Math.PI * 3) % TAU) - Math.PI;
690:     dog.root.rotation.y += diff * Math.min(1, dt * 8);
691:   }
692:   dog.root.position.y = groundHeight(dog.root.position.x, dog.root.position.z);
693:   dog.walk += dt * (moving ? player.speed * 2.4 + 4 : 1.5);
694:   const sw = Math.sin(dog.walk) * 0.55;
695:   dog.legs[0].rotation.x = sw;
696:   dog.legs[1].rotation.x = -sw;
697:   dog.legs[2].rotation.x = -sw;
698:   dog.legs[3].rotation.x = sw;
699:   dog.tail.rotation.x = -0.2 + Math.sin(game.time * 5) * 0.15;
700:   dog.tail.rotation.z = Math.sin(game.time * 3.5) * 0.18;
701:   dog.head.rotation.y = Math.sin(game.time * 0.6) * 0.12;
702:   if (game.dogBark > 0) {
703:     game.dogBark = Math.max(0, game.dogBark - dt * 1.8);
704:     dog.head.position.y = 0.6 + Math.sin(game.dogBark * 18) * 0.035;
705:     if (Math.random() < dt * 6) audio.bark();
706:   } else {
707:     dog.head.position.y = 0.6;
708:   }
709:   if (moving && player.speed > 4 && Math.random() < dt * 4) {
710:     particles.emit(dog.root.position.x, dog.root.position.y + 0.05, dog.root.position.z, 0xa89a82,
711:       { count: 1, speed: 0.4, spread: 0.3, up: 0.3, life: 0.4, gravity: 0.2, drag: 3 });
712:   }
713: }
