715: function updateWisps(dt) {
716:   const px = player.x, pz = player.z;
717:   for (const w of wisps) {
718:     if (!w.alive) continue;
719:     w.phase += dt;
720:     w.hit = Math.max(0, w.hit - dt);
721:     const pos = w.root.position;
722:     const dx = px - pos.x, dz = pz - pos.z;
723:     const dist = Math.hypot(dx, dz);
724: 
725:     // knockback
726:     pos.x += (w.kx || 0) * dt;
727:     pos.z += (w.kz || 0) * dt;
728:     w.kx = damp(w.kx || 0, 0, 6, dt);
729:     w.kz = damp(w.kz || 0, 0, 6, dt);
730: 
731:     const active = game.mode === 'hunt' && !game.ended;
732:     if (active && dist < 25) w.aggro = true;
733: 
734:     let hoverY;
735:     if (active && w.aggro) {
736:       if (dist > 4.1) {
737:         const sp = 2.15 + Math.sin(w.phase * 1.3) * 0.4;
738:         pos.x += dx / (dist || 1) * sp * dt;
739:         pos.z += dz / (dist || 1) * sp * dt;
740:       } else if (dist < 2.5) {
741:         pos.x -= dx / (dist || 1) * 1.2 * dt;
742:         pos.z -= dz / (dist || 1) * 1.2 * dt;
743:       } else {
744:         pos.x += (-dz / (dist || 1)) * 0.8 * dt;
745:         pos.z += (dx / (dist || 1)) * 0.8 * dt;
746:       }
747:       hoverY = groundHeight(pos.x, pos.z) + 1.45 + Math.sin(w.phase * 2.2) * 0.22;
748:       w.fire -= dt;
749:       const canSee = dist < 20;
750:       if (w.fire <= 0 && canSee && game.mode === 'hunt') {
751:         w.fire = 2.4 + Math.random() * 1.2;
752:         const origin = new THREE.Vector3(pos.x, pos.y, pos.z);
753:         const target = new THREE.Vector3(player.x, player.y + 0.95, player.z);
754:         bolts.spawn(origin, target, 8.5);
755:         audio.bolt();
756:         w.glow.material.opacity = 1;
757:         particles.emit(pos.x, pos.y, pos.z, 0xffb066, { count: 8, speed: 1.6, spread: 0.8, up: 1.2, life: 0.4, gravity: -1, drag: 2 });
758:       }
