114:   const colors = new Float32Array(pos.count * 3);
115:   const dark = new THREE.Color(0x24371f), light = new THREE.Color(0x55693a);
116:   const heather = new THREE.Color(0x594b52), path = new THREE.Color(0x8f7c56);
117:   const mud = new THREE.Color(0x3d4133), rock = new THREE.Color(0x5b5d49);
118:   const c = new THREE.Color();
119:   const shrineTint = new THREE.Color(0x767250);
120: 
121:   for (let i = 0; i < pos.count; i++) {
122:     const x = pos.getX(i), z = pos.getZ(i);
123:     const y = terrainHeight(x, z);
124:     pos.setY(i, y);
125: 
126:     const patch = (Math.sin(x * 0.22 + 1.7) + Math.sin(z * 0.19 - 0.4) + Math.sin((x + z) * 0.11) + 3) / 6;
127:     c.copy(dark).lerp(light, clamp(patch * 1.15, 0, 1));
128:     const hp = Math.sin(x * 0.087 + 2.1) * Math.sin(z * 0.075 - 1.2);
129:     if (hp > 0.34) c.lerp(heather, smoothstep(0.34, 0.75, hp) * 0.42);
130:     const dp = pathDist(x, z);
131:     if (dp < 3.6) c.lerp(path, smoothstep(3.6, 0.8, dp) * 0.95);
132:     const ds = streamDist(x, z);
133:     if (ds < 9.5) c.lerp(mud, smoothstep(9.5, 4.4, ds) * 0.85);
134:     if (y > 3.4) c.lerp(rock, smoothstep(3.4, 5.8, y) * 0.5);
135:     const shrineD = Math.hypot(x - SHRINE_POS.x, z - SHRINE_POS.z);
136:     if (shrineD < 13) c.lerp(shrineTint, smoothstep(13, 4, shrineD) * 0.45);
137:     const jitter = 0.92 + ((Math.sin(x * 12.9 + z * 7.3) * 0.5 + 0.5) * 0.16);
138:     colors[i * 3] = c.r * jitter; colors[i * 3 + 1] = c.g * jitter; colors[i * 3 + 2] = c.b * jitter;
139:   }
140:   geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
141:   geo.computeVertexNormals();
142:   const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.97, metalness: 0.0 });
143:   const mesh = new THREE.Mesh(geo, mat);
144:   mesh.receiveShadow = true;
145:   mesh.castShadow = false;
146:   scene.add(mesh);
147:   return mesh;
148: }
