150: /* ------------------------------------------------------------------ *
151:  *  Water ribbon
152:  * ------------------------------------------------------------------ */
153: function buildWater(scene) {
154:   const pts = STREAM_SAMPLES;
155:   const positions = [], uvs = [], indices = [];
156:   for (let i = 0; i < pts.length; i++) {
157:     const a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)];
158:     const tx = b.x - a.x, tz = b.z - a.z;
159:     const l = Math.hypot(tx, tz) || 1;
160:     const nx = -tz / l, nz = tx / l;
161:     const w = 3.0 + Math.sin(i * 0.21) * 0.55 + Math.sin(i * 0.07) * 0.45;
162:     positions.push(pts[i].x - nx * w, WATER_Y, pts[i].z - nz * w);
163:     positions.push(pts[i].x + nx * w, WATER_Y, pts[i].z + nz * w);
164:     uvs.push(0, i * 0.12, 1, i * 0.12);
165:     if (i < pts.length - 1) {
166:       const k = i * 2;
167:       indices.push(k, k + 2, k + 1, k + 1, k + 2, k + 3);
168:     }
169:   }
170:   const geo = new THREE.BufferGeometry();
171:   geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
172:   geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
173:   geo.setIndex(indices);
174:   geo.computeVertexNormals();
175: 
176:   const mat = new THREE.ShaderMaterial({
177:     transparent: true, depthWrite: false, fog: true,
178:     uniforms: THREE.UniformsUtils.merge([
179:       THREE.UniformsLib.fog,
180:       {
181:         uTime: { value: 0 },
182:         uDeep: { value: new THREE.Color(0x31524f) },
183:         uShallow: { value: new THREE.Color(0x67897a) },
184:         uSun: { value: new THREE.Color(0xffd39a) },
185:         uSunDir: { value: SUN_DIR.clone() },
186:       },
187:     ]),
188:     vertexShader: `
189:       uniform float uTime;
190:       varying vec3 vWorld;
191:       varying vec2 vUv;
192:       #include <fog_pars_vertex>
193:       void main(){
194:         vUv = uv;
195:         vec3 p = position;
196:         p.y += sin(p.x * 1.7 + uTime * 1.2) * 0.016 + sin(p.z * 2.4 - uTime * 0.8) * 0.012;
197:         vec4 mvPosition = modelViewMatrix * vec4(p, 1.0);
198:         gl_Position = projectionMatrix * mvPosition;
199:         vWorld = (modelMatrix * vec4(p, 1.0)).xyz;
200:         #include <fog_vertex>
201:       }`,
202:     fragmentShader: `
203:       uniform float uTime;
204:       uniform vec3 uDeep, uShallow, uSun, uSunDir;
205:       varying vec3 vWorld;
206:       varying vec2 vUv;
207:       #include <fog_pars_fragment>
208:       void main(){
209:         vec3 viewDir = normalize(cameraPosition - vWorld);
210:         float fres = pow(1.0 - clamp(viewDir.y, 0.0, 1.0), 2.2);
211:         float r1 = sin(vWorld.x * 2.2 + uTime * 1.1) * 0.5 + 0.5;
212:         float r2 = sin(vWorld.z * 1.8 - uTime * 0.85 + sin(vWorld.x * 0.6)) * 0.5 + 0.5;
213:         float ripple = r1 * r2;
214:         vec3 col = mix(uDeep, uShallow, 0.2 + fres * 0.55 + ripple * 0.22);
215:         float streak = pow(max(0.0, 1.0 - abs(vWorld.x * 0.045 + 0.4)), 5.0);
216:         col += uSun * streak * 0.10 * (0.6 + ripple);
217:         float glint = pow(ripple, 26.0);
218:         col += uSun * glint * 0.5;
219:         gl_FragColor = vec4(col, 0.87);
220:         #include <tonemapping_fragment>
221:         #include <colorspace_fragment>
222:         #include <fog_fragment>
223:       }`,
224:   });
225:   const mesh = new THREE.Mesh(geo, mat);
226:   mesh.renderOrder = 1;
227:   scene.add(mesh);
228:   return { mesh, mat };
229: }
