231: /* ------------------------------------------------------------------ *
232:  *  Instancing helpers
233:  * ------------------------------------------------------------------ */
234: /* Merge transformed geometry copies into one buffer. */
235: function mergeParts(parts) {
236:   const geos = [];
237:   for (const part of parts) {
238:     const g = part.geo.clone();
239:     if (part.scale) g.scale(part.scale[0], part.scale[1], part.scale[2]);
240:     if (part.pos) g.translate(part.pos[0], part.pos[1], part.pos[2]);
241:     geos.push(g);
242:   }
243:   const positions = [], normals = [], uvs = [], indices = [];
244:   let offset = 0;
245:   for (const g of geos) {
246:     const p = g.attributes.position, n = g.attributes.normal, u = g.attributes.uv, idx = g.index;
247:     for (let i = 0; i < p.count; i++) {
248:       positions.push(p.getX(i), p.getY(i), p.getZ(i));
249:       normals.push(n.getX(i), n.getY(i), n.getZ(i));
250:       if (u) uvs.push(u.getX(i), u.getY(i));
251:     }
252:     if (idx) for (let i = 0; i < idx.count; i++) indices.push(idx.getX(i) + offset);
253:     else for (let i = 0; i < p.count; i++) indices.push(i + offset);
254:     offset += p.count;
255:   }
256:   const geo = new THREE.BufferGeometry();
257:   geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
258:   geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
259:   if (uvs.length) geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
260:   geo.setIndex(indices);
261:   return geo;
262: }
