264: /* Merge a few crossed, slightly bent blades into one tuft geometry. */
265: function tuftGeometry(bladeW, bladeH, blades, lean = 0.06) {
266:   const geos = [];
267:   for (let i = 0; i < blades; i++) {
268:     const g = new THREE.PlaneGeometry(bladeW, bladeH, 1, 3);
269:     g.translate(0, bladeH / 2, 0);
270:     const p = g.attributes.position;
271:     for (let j = 0; j < p.count; j++) {
272:       const y = p.getY(j);
273:       p.setX(j, p.getX(j) + (y / bladeH) ** 2 * lean);
274:     }
275:     g.rotateY(i * Math.PI / blades);
276:     geos.push(g);
277:   }
278:   const positions = [], normals = [], uvs = [], indices = [];
279:   let offset = 0;
280:   for (const g of geos) {
281:     const p = g.attributes.position, n = g.attributes.normal, u = g.attributes.uv, idx = g.index;
282:     for (let i = 0; i < p.count; i++) {
283:       positions.push(p.getX(i), p.getY(i), p.getZ(i));
284:       normals.push(n.getX(i), n.getY(i), n.getZ(i));
285:       uvs.push(u.getX(i), u.getY(i));
286:     }
287:     for (let i = 0; i < idx.count; i++) indices.push(idx.getX(i) + offset);
288:     offset += p.count;
289:   }
290:   const geo = new THREE.BufferGeometry();
291:   geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
292:   geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
293:   geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
294:   geo.setIndex(indices);
295:   return geo;
296: }
