298: const dummy = new THREE.Object3D();
299: function fillInstance(mesh, i, x, y, z, rot, sx, sy, sz) {
300:   dummy.position.set(x, y, z);
301:   dummy.rotation.set(0, rot, 0);
302:   dummy.scale.set(sx, sy, sz);
303:   dummy.updateMatrix();
304:   mesh.setMatrixAt(i, dummy.matrix);
305: }
