307: let _grassTexture = null;
308: function grassTexture() {
309:   if (_grassTexture) return _grassTexture;
310:   const c = document.createElement('canvas');
311:   c.width = 128; c.height = 128;
312:   const g = c.getContext('2d');
313:   g.clearRect(0, 0, 128, 128);
314:   g.lineCap = 'round';
315:   const r = seeded(3311);
316:   for (let i = 0; i < 26; i++) {
317:     const bx = 8 + r() * 112;
318:     const tx = bx + (r() - 0.5) * 40;
319:     const ty = 6 + r() * 54;
320:     const cx = bx + (r() - 0.5) * 18;
321:     const cy = 60 + r() * 24;
322:     const w = 1.4 + r() * 2.8;
323:     const shade = 200 + r() * 50;
324:     g.strokeStyle = `rgba(${shade},${shade + 20},${shade - 35},${0.75 + r() * 0.25})`;
325:     g.lineWidth = w;
326:     g.beginPath();
327:     g.moveTo(bx, 128);
328:     g.quadraticCurveTo(cx, cy, tx, ty);
329:     g.stroke();
330:     if (r() > 0.7) {
331:       g.fillStyle = `rgba(${shade + 20},${shade + 30},${shade - 20},0.85)`;
332:       g.beginPath();
333:       g.ellipse(tx, ty, 1.7 + r() * 1.6, 3.5 + r() * 3, (r() - 0.5) * 0.5, 0, TAU);
334:       g.fill();
335:     }
336:   }
337:   const tex = new THREE.CanvasTexture(c);
338:   tex.colorSpace = THREE.SRGBColorSpace;
339:   tex.wrapS = tex.wrapT = THREE.ClampToEdgeWrapping;
340:   tex.minFilter = THREE.LinearMipmapLinearFilter;
341:   tex.magFilter = THREE.LinearFilter;
342:   _grassTexture = tex;
343:   return tex;
344: }
