346: function windMaterial(hex, height, map = null) {
347:   const timeU = { value: 0 };
348:   const mat = new THREE.MeshLambertMaterial({
349:     color: hex, side: THREE.DoubleSide, map,
350:     alphaTest: map ? 0.32 : 0, transparent: false,
351:   });
352:   mat.onBeforeCompile = (shader) => {
353:     shader.uniforms.uTime = timeU;
354:     shader.vertexShader = 'uniform float uTime;\n' + shader.vertexShader;
355:     shader.vertexShader = shader.vertexShader.replace('#include <begin_vertex>', `#include <begin_vertex>
356:       #ifdef USE_INSTANCING
357:         float ph = instanceMatrix[3].x * 0.55 + instanceMatrix[3].z * 0.71;
358:         float sway = sin(uTime * 1.45 + ph) * 0.15 + sin(uTime * 2.9 + ph * 1.7) * 0.045;
359:         float w = pow(max(position.y, 0.0) / ${height.toFixed(2)}, 1.65);
360:         transformed.x += sway * w;
361:         transformed.z += sway * 0.55 * w;
362:       #endif`);
363:   };
364:   mat.userData.timeU = timeU;
365:   return mat;
366: }
