368: /* ------------------------------------------------------------------ *
369:  *  World
370:  * ------------------------------------------------------------------ */
371: export function createWorld(scene, particles) {
372:   const updaters = [];
373:   const sky = buildSky(scene);
374:   updaters.push((dt, t) => { sky.mat.uniforms.uTime.value = t; });
375: 
376:   // Ground skirt beyond the playable terrain.
377:   const skirt = new THREE.Mesh(
378:     new THREE.CircleGeometry(320, 48),
379:     new THREE.MeshBasicMaterial({ color: 0x2c3a33, fog: true })
380:   );
381:   skirt.rotation.x = -Math.PI / 2;
382:   skirt.position.y = -4.5;
383:   scene.add(skirt);
384: 
385:   const ridgeMat = new THREE.MeshBasicMaterial({ vertexColors: true, fog: true, side: THREE.DoubleSide });
386:   const ridgeNear = new THREE.Mesh(ridgeRing(99, 127, -8, 6, 19, 19, 0x1e322e, 0x3a5a52), ridgeMat);
387:   scene.add(ridgeNear);
388:   const ridgeMid = new THREE.Mesh(ridgeRing(124, 166, -10, 15, 36, 41, 0x294743, 0x4e6f67), ridgeMat);
389:   scene.add(ridgeMid);
390:   const ridgeFar = new THREE.Mesh(ridgeRing(162, 238, -14, 28, 58, 77, 0x3e5c56, 0x71877e), ridgeMat);
391:   scene.add(ridgeFar);
392: 
393:   const terrain = buildTerrain(scene);
394:   const water = buildWater(scene);
395:   updaters.push((dt, t) => { water.mat.uniforms.uTime.value = t; });
396: 
397:   /* --- forest ----------------------------------------------------- */
398:   const rng = seeded(90210);
399:   const treeData = [];
400:   const minD = (x, z) => Math.min(
401:     Math.hypot(x - KEEPER_POS.x, z - KEEPER_POS.z),
402:     Math.hypot(x - SHRINE_POS.x, z - SHRINE_POS.z),
403:     Math.hypot(x - START.x, z - START.z),
404:   );
405:   let attempts = 0;
406:   while (treeData.length < QUALITY.trees && attempts++ < 4000) {
407:     const x = rand(94, -94), z = rand(94, -94);
408:     if (pathDist(x, z) < 4.6 || streamDist(x, z) < 11.5) continue;
409:     if (minD(x, z) < 11) continue;
410:     if (Math.hypot(x, z) > 92) continue;
411:     if (treeData.some(t => (t.x - x) ** 2 + (t.z - z) ** 2 < 17)) continue;
412:     treeData.push({ x, z, s: rand(1.45, 0.72), r: rand(TAU, 0), type: rng() < 0.34 ? 'conifer' : 'broad' });
413:   }
414:   const treeColliders = treeData.map(t => ({ x: t.x, z: t.z, r: 0.55 * t.s }));
415: 
416:   const trunkGeo = new THREE.CylinderGeometry(0.16, 0.34, 3.5, 6);
417:   trunkGeo.translate(0, 1.75, 0);
418:   const coneGeo = new THREE.ConeGeometry(1.62, 3.5, 7);
419:   coneGeo.translate(0, 3.9, 0);
420:   const coneTopGeo = new THREE.ConeGeometry(1.08, 2.4, 7);
421:   coneTopGeo.translate(0, 5.7, 0);
422:   const broadGeo = mergeParts([
423:     { geo: new THREE.IcosahedronGeometry(1, 1), pos: [0, 4.15, 0], scale: [1.72, 1.38, 1.72] },
424:     { geo: new THREE.IcosahedronGeometry(1, 1), pos: [1.02, 3.35, 0.34], scale: [1.08, 0.82, 1.08] },
425:     { geo: new THREE.IcosahedronGeometry(1, 1), pos: [-0.98, 3.4, -0.28], scale: [1.0, 0.78, 1.0] },
426:     { geo: new THREE.IcosahedronGeometry(1, 1), pos: [0.1, 5.25, -0.12], scale: [0.94, 0.74, 0.94] },
427:   ]);
428: 
429:   const trunkMat = new THREE.MeshStandardMaterial({ color: 0x66513b, roughness: 0.95, flatShading: true });
430:   const leafMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.92, flatShading: true });
431: 
432:   const broadTrees = treeData.filter(t => t.type === 'broad');
433:   const conifTrees = treeData.filter(t => t.type === 'conifer');
434:   const trunks = new THREE.InstancedMesh(trunkGeo, trunkMat, treeData.length);
435:   const broadLeaves = new THREE.InstancedMesh(broadGeo, leafMat, broadTrees.length);
436:   const coneLeaves = new THREE.InstancedMesh(coneGeo, leafMat, conifTrees.length);
437:   const coneTops = new THREE.InstancedMesh(coneTopGeo, leafMat, conifTrees.length);
438:   const leafA = new THREE.Color(), leafB = new THREE.Color();
439: 
440:   treeData.forEach((t, i) => {
441:     const y = terrainHeight(t.x, t.z) - 0.15;
442:     fillInstance(trunks, i, t.x, y, t.z, t.r, t.s, t.s, t.s);
443:   });
444:   broadTrees.forEach((t, i) => {
445:     const y = terrainHeight(t.x, t.z) - 0.15;
446:     fillInstance(broadLeaves, i, t.x, y, t.z, t.r, t.s, t.s, t.s);
447:     leafA.setHSL(0.235 + rng() * 0.09, 0.4 + rng() * 0.16, 0.2 + rng() * 0.13);
448:     broadLeaves.setColorAt(i, leafA);
449:   });
450:   conifTrees.forEach((t, i) => {
451:     const y = terrainHeight(t.x, t.z) - 0.15;
452:     fillInstance(coneLeaves, i, t.x, y, t.z, t.r, t.s, t.s, t.s);
453:     fillInstance(coneTops, i, t.x, y, t.z, t.r + 0.35, t.s, t.s, t.s);
454:     const hue = 0.29 + rng() * 0.06;
455:     const light = 0.17 + rng() * 0.1;
456:     leafA.setHSL(hue, 0.36, light);
457:     leafB.setHSL(hue, 0.34, light + 0.05);
458:     coneLeaves.setColorAt(i, leafA);
459:     coneTops.setColorAt(i, leafB);
460:   });
461:   [trunks, broadLeaves, coneLeaves, coneTops].forEach(m => {
462:     m.castShadow = true; m.receiveShadow = true; m.instanceMatrix.needsUpdate = true; scene.add(m);
463:   });
464: 
465:   /* --- blossom trees near shrine -------------------------------- */
466:   const blossomSpots = [
467:     [24, -18], [42, -36], [17, -40], [6, -16], [-13, 4], [45, -10], [-39, 30],
468:   ];
469:   const blossomMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9, flatShading: true });
470:   const blossomTrees = new THREE.InstancedMesh(broadGeo, blossomMat, blossomSpots.length);
471:   const blossomTrunks = new THREE.InstancedMesh(trunkGeo, new THREE.MeshStandardMaterial({ color: 0x5d4937, roughness: 0.95, flatShading: true }), blossomSpots.length);
472:   const blossomGlows = [];
473:   const pinkA = new THREE.Color(0xd9a9a2), pinkB = new THREE.Color(0xf3d1c6);
474:   blossomSpots.forEach(([x, z], i) => {
475:     const y = terrainHeight(x, z) - 0.1;
476:     const s = rand(1.05, 0.78);
477:     fillInstance(blossomTrunks, i, x, y, z, rand(TAU, 0), s, s, s);
478:     fillInstance(blossomTrees, i, x, y, z, rand(TAU, 0), s, s, s);
479:     blossomTrees.setColorAt(i, pinkA.clone().lerp(pinkB, rand(1, 0)));
480:     const glow = glowSprite(0xffd9c4, 3.2, 0.16);
481:     glow.position.set(x, y + 4.7 * s, z);
482:     scene.add(glow);
483:     blossomGlows.push({ sprite: glow, phase: rand(TAU, 0), y: y + 4.7 * s });
484:   });
485:   [blossomTrunks, blossomTrees].forEach(m => { m.castShadow = true; m.receiveShadow = true; m.instanceMatrix.needsUpdate = true; scene.add(m); });
486:   updaters.push((dt, t) => {
487:     for (const b of blossomGlows) {
488:       const k = 0.13 + 0.06 * Math.sin(t * 1.1 + b.phase);
489:       b.sprite.material.opacity = k;
490:       b.sprite.position.y = b.y + Math.sin(t * 0.7 + b.phase) * 0.15;
491:     }
492:     if (particles && Math.random() < dt * 3.2) {
493:       const p = blossomSpots[Math.floor(Math.random() * blossomSpots.length)];
494:       particles.emit(p[0] + rand(1.4, -1.4), terrainHeight(p[0], p[1]) + rand(4.2, 3.2), p[1] + rand(1.4, -1.4), 0xe7b7ab, { count: 1, speed: 0.12, up: -0.25, gravity: -0.22, drag: 0.5, life: 4.5, spread: 0.18 });
495:     }
496:   });
497: 
498:   /* --- rocks ----------------------------------------------------- */
499:   const rockData = [];
500:   let ra = 0;
501:   while (rockData.length < QUALITY.rocks && ra++ < 900) {
502:     const angle = rand(TAU, 0), radius = rand(88, 9);
503:     const x = Math.cos(angle) * radius, z = Math.sin(angle) * radius;
504:     if (pathDist(x, z) < 2.5) continue;
505:     if (minD(x, z) < 8) continue;
506:     const nearWater = streamDist(x, z) < 12;
507:     if (!nearWater && rng() > 0.45) continue;
508:     rockData.push({ x, z, s: rand(nearWater ? 1.4 : 0.7, nearWater ? 0.35 : 0.22), r: rand(TAU, 0) });
509:   }
510:   const rockGeo = new THREE.DodecahedronGeometry(1, 0);
511:   const rocks = new THREE.InstancedMesh(rockGeo, new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.92, flatShading: true }), rockData.length);
512:   const rockCol = new THREE.Color();
513:   rockData.forEach((r, i) => {
514:     fillInstance(rocks, i, r.x, terrainHeight(r.x, r.z) - r.s * 0.2, r.z, r.r, r.s * rand(1.3, 0.8), r.s * rand(0.7, 0.4), r.s * rand(1.2, 0.7));
515:     rockCol.setHSL(0.24, 0.06, 0.24 + rng() * 0.09);
516:     rocks.setColorAt(i, rockCol);
517:   });
518:   rocks.castShadow = true; rocks.receiveShadow = true; rocks.instanceMatrix.needsUpdate = true;
519:   scene.add(rocks);
520: 
